def lookup_tesou_by_number(num):
    """番号キーで手相データを取得（同一番号が複数ある場合はリストで返す）"""
    if num is None:
        return []
    key = str(num).strip()
    return TESOU_NUMBER_TABLE.get(key, [])

def lookup_shichu_by_number(num):
    """番号キーで四柱推命データを取得（同一番号が複数ある場合はリストで返す）"""
    if num is None:
        return []
    key = str(num).strip()
    return SHICHU_NUMBER_TABLE.get(key, [])

def get_tesou_explanation(line_name: str, shape: str = None, lang: str = "ja") -> str:
    """線名 + 形状 から解説文を返す（無ければ従来辞書へフォールバック）"""
    name = (line_name or "").strip()
    shape_key = (shape or "").strip()
    lang_norm = (lang or "ja").lower()
    if shape_key:
        d = tesou_shapes.get(name, {}).get(shape_key)
        if isinstance(d, dict):
            # language fallback: ja -> en -> zh -> ko
            return d.get(lang_norm[:2]) or d.get("ja") or d.get("en") or d.get("zh") or d.get("ko") or tesou_descriptions.get(name, "")
        elif isinstance(d, str):
            return d
    return tesou_descriptions.get(name, "")

def build_shape_guide_text(lang: str = "ja") -> str:
    """OpenAI へのプロンプトに渡す『形状別の意味ガイド』を生成"""
    lang_norm = (lang or "ja").lower()
    out = []
    for line_name, shapes in tesou_shapes.items():
        out.append(f"【{line_name}】")
        for shape_key, txt in shapes.items():
            if isinstance(txt, dict):
                body = txt.get(lang_norm[:2]) or txt.get("ja") or txt.get("en") or txt.get("zh") or txt.get("ko") or ""
            else:
                body = str(txt)
            if not body:
                continue
            out.append(f"- {shape_key}: {body}")
        out.append("")
    return "\n".join(out).strip()
